/** Public reference metadata only. Original resource/source registries are not rewritten. */
final class CAFCC_Resource_Matrix {
    public static function table(){global $wpdb;return $wpdb->prefix.'cafcc_resource_index';}
    public static function migrate(){global $wpdb;$t=self::table();dbDelta("CREATE TABLE $t (
