    public static function rows(){
        global $wpdb;$t=self::table();$rows=$wpdb->get_results("SELECT id,revision,course,scheme,subject_key,resource_type,attempt_month,attempt_year,series,language,availability,title,url,source_hash FROM $t WHERE publication_status='published' ORDER BY attempt_year DESC,attempt_month DESC,id LIMIT 3000",ARRAY_A);$safe=array();foreach($rows as $row){if(!self::safe_url($row['url'],$row['source_hash']))continue;$row['origin']='Owner-verified resource index';$safe[]=$row;}
        // The exact-hash public copy overlay already records owner-selected, byte-checked PDFs.
        $copies=CAFCC_Public_Sources::table();$sources=CAFCC_Sources::table();$registered=$wpdb->get_results("SELECT s.id,s.source_hash,s.payload,p.title AS copy_title FROM $sources s JOIN $copies p ON p.source_hash=s.source_hash AND p.state='active' ORDER BY s.id LIMIT 1000",ARRAY_A);
        foreach($registered as $r){$d=json_decode($r['payload'],true);if(($d['selection_state']??'')!=='owner_verified'||($d['technical_state']??'')!=='pdf_checked'||($d['content_origin']??'')!=='icai'||!preg_match('/^(January|February|March|April|May|June|July|August|September|October|November|December)\s+(20\d{2})$/i',$d['exam_attempt']??'',$m))continue;$role=$d['role'];$copy=CAFCC_Public_Sources::find($r['source_hash'],$role==='answers'?'answer':'question');if(!$copy)continue;
            $type=$d['source_type']==='exam'?($role==='questions'?'exam':'suggested_answers'):$d['source_type'];if(!in_array($type,array('rtp','mtp','exam','suggested_answers','study_material'),true))continue;
            // An answer book with included questions is not relabelled as a question-only paper.
            if($type==='exam'&&preg_match('/suggested|answer/i',$d['title']))$type='suggested_answers';$item=array('id'=>1000000000+(int)$r['id'],'course'=>'final','scheme'=>'new_scheme_2024','subject_key'=>$d['subject_code'],'resource_type'=>$type,'attempt_month'=>(int)date('n',strtotime($m[1].' 1 2000')),'attempt_year'=>(int)$m[2],'series'=>$d['mtp_series'],'language'=>'en','availability'=>'available','title'=>$d['title'],'url'=>$copy['url'],'source_hash'=>$r['source_hash'],'role'=>$role,'origin'=>'Exact-hash owner-public ICAI PDF copy');$safe[]=$item;
        }
