    }
    public static function safe_url($url,$hash=''){
        if(!is_string($url)||strlen($url)>2048)return false;$official=CAFCC_Repository::official_url($url);if(!is_wp_error($official)&&$official)return true;
        if(!preg_match('~^https://drive\.google\.com/file/d/([A-Za-z0-9_-]{10,120})/view$~D',$url,$m))return false;foreach(array('question','answer') as $kind){$copy=CAFCC_Public_Sources::find($hash,$kind);if($copy&&$copy['drive_file_id']===$m[1])return true;}return false;
    }
    public static function mtp($id,$course,$subject){foreach(self::rows() as $r)if((int)$r['id']===$id&&$r['course']===$course&&(!$subject||$r['subject_key']===$subject)&&$r['resource_type']==='mtp'&&$r['availability']==='available'&&($r['role']??'questions')!=='answers')return $r;return false;}
    public static function matrix($r){
        $course=$r->get_param('course')??'final';if(!is_string($course))return CAFCC_Repository::error('Choose a course.');$c=CAFCC_Courses::all()[$course]??null;if(!$c)return CAFCC_Repository::error('Choose a course.');$group=$r->get_param('group')??'both';if($course==='foundation')$group='none';if(!in_array($group,array('1','2','both','none'),true))return CAFCC_Repository::error('Choose a course group.');$attempt=$r->get_param('attempt')??'';$language=$r->get_param('language')??'';if(!is_string($attempt)||strlen($attempt)>30||!in_array($language,array('','en','hi'),true))return CAFCC_Repository::error('Invalid resource filter.');$rows=array_values(array_filter(self::rows(),function($x)use($course,$language){return $x['course']===$course&&$x['scheme']==='new_scheme_2024'&&(!$language||$x['language']===$language);}));$attempts=array();foreach($rows as $x)$attempts[]=CAFCC_Courses::period((int)$x['attempt_month'],(int)$x['attempt_year']);$attempts=CAFCC_Experience::sort_attempts(array_values(array_unique($attempts)));if(!$attempt&&$attempts)$attempt=$attempts[0];$columns=CAFCC_Courses::subjects($course,$group);$keys=array_column($columns,'key');$rows=array_values(array_filter($rows,function($x)use($attempt,$keys){return in_array($x['subject_key'],$keys,true)&&CAFCC_Courses::period((int)$x['attempt_month'],(int)$x['attempt_year'])===$attempt;}));
        return array('course'=>$c,'columns'=>$columns,'attempt'=>$attempt,'attempts'=>$attempts,'resources'=>$rows,'missing_state'=>'Not indexed','rows'=>array('rtp'=>'RTP','mtp'=>'MTP','exam'=>'Examination Question Paper','suggested_answers'=>'Suggested Answers'),'more_rows'=>array('study_material'=>'Study Material','supplementary'=>'Supplementary Material','notification'=>'Official Notifications'),'directories'=>self::directories($course),'note'=>'ICAI is the authoritative source. Check current ICAI notifications for material and applicability. This is an independent preparation platform, not affiliated with ICAI. Missing links mean not indexed unless an explicit, reviewed availability notice says otherwise.');
    }
    public static function directories($course){
        $c=CAFCC_Courses::all()[$course];$out=array(array('title'=>'Official ICAI course directory (web page, not a specific PDF)','url'=>$c['source_url']));global $wpdb;$t=CAFCC_Bank_DB::table('resources');$rows=$course==='final'?$wpdb->get_results("SELECT title,official_url FROM $t WHERE review_status='verified' AND publication_status='published' ORDER BY id LIMIT 200",ARRAY_A):array();foreach($rows as $r)if(!is_wp_error(CAFCC_Repository::official_url($r['official_url'])))$out[]=array('title'=>$r['title'].' (existing official reference)','url'=>$r['official_url']);return $out;
    }
    public static function save($d){
        if(!CAFCC_Repository::admin_allowed())return CAFCC_Repository::error('Administrator required.',403);$allowed=array('id','expected_revision','course','subject_key','resource_type','attempt_month','attempt_year','series','language','availability','title','url','source_hash','publish_confirmed');if(!is_array($d)||array_diff(array_keys($d),$allowed))return CAFCC_Repository::error('Unexpected resource fields.');$course=$d['course']??'';if(!is_string($course))return CAFCC_Repository::error('Choose a course.');$c=CAFCC_Courses::all()[$course]??null;if(!$c||!in_array($d['subject_key']??'',array_column($c['subjects'],'key'),true))return CAFCC_Repository::error('Choose a paper in the selected course.');if(!CAFCC_Courses::month($d['attempt_month']??null,$d['attempt_year']??null)||sprintf('%04d-%02d',$d['attempt_year'],$d['attempt_month'])<$c['from'])return CAFCC_Repository::error('This source requires a separately indexed historical scheme.');
        $type=$d['resource_type']??'';$availability=$d['availability']??'available';$series=$d['series']??'';$language=$d['language']??'en';if(!in_array($type,array('rtp','mtp','exam','suggested_answers','study_material','supplementary','notification'),true)||!in_array($availability,array('available','not_released'),true)||!in_array($series,array('','I','II'),true)||!in_array($language,array('en','hi'),true)||($type!=='mtp'&&$series))return CAFCC_Repository::error('Choose a valid resource type, series and availability.');$title=CAFCC_Planner::text($d['title']??'');$url=$d['url']??'';$hash=$d['source_hash']??'';if(is_wp_error($title)||!$title||!is_string($hash)||($hash&&!preg_match('/^[a-f0-9]{64}$/D',$hash))||!self::safe_url($url,$hash))return CAFCC_Repository::error('Use a verified ICAI URL or an existing exact-hash owner-public Drive copy. Third-party mirrors and private Drive links are rejected.');if($availability==='available'&&in_array($type,array('rtp','mtp','exam','suggested_answers','study_material'),true)&&!preg_match('~\.pdf(?:$|[?#])|^https://drive\.google\.com/file/d/~i',$url))return CAFCC_Repository::error('This row needs an exact PDF link. Put course landing pages in official directories, not PDF cells.');$id=$d['id']??0;if(!is_int($id)||$id<0||!is_bool($d['publish_confirmed']??false))return CAFCC_Repository::error('Use a valid resource revision and explicit publication decision.');
        return CAFCC_Academic::transaction(function()use($d,$id,$course,$type,$availability,$title,$url,$hash,$series,$language){global $wpdb;$t=self::table();$old=$id?$wpdb->get_row($wpdb->prepare("SELECT * FROM $t WHERE id=%d FOR UPDATE",$id),ARRAY_A):null;if($id&&(!$old||(int)$old['revision']!==($d['expected_revision']??null)))return CAFCC_Repository::error('Resource changed; reload its current revision.',409);$v=array('course'=>$course,'scheme'=>'new_scheme_2024','subject_key'=>$d['subject_key'],'resource_type'=>$type,'attempt_month'=>$d['attempt_month'],'attempt_year'=>$d['attempt_year'],'series'=>$series,'language'=>$language,'availability'=>$availability,'title'=>$title,'url'=>$url,'source_hash'=>$hash,'publication_status'=>!empty($d['publish_confirmed'])?'published':'draft','revision'=>$old?(int)$old['revision']+1:1,'reviewer_id'=>get_current_user_id(),'updated_at'=>current_time('mysql',true));if(false===($id?$wpdb->update($t,$v,array('id'=>$id)):$wpdb->insert($t,$v)))return CAFCC_Repository::error('Cannot save resource index.',503);$id=$id?:$wpdb->insert_id;if(!CAFCC_Bank_DB::audit_master('resource_index',$id,$old,$v))return CAFCC_Repository::error('Cannot retain resource provenance.',503);return array_merge($v,array('id'=>$id));});
    }
    public static function screen(){CAFCC_Experience::assets();wp_enqueue_script('cafcc-resource-matrix',plugins_url('assets/resources-v8.js',CAFCC_FILE),array('cafcc-experience','cafcc-net'),CAFCC_VERSION,true);return '<section class="cc-resources-v8" data-resource-matrix><header class="cc-page-heading"><div><h1>ICAI Resources</h1><p>Source-backed links, organised by course and attempt.</p></div></header><form class="cc-resource-filters"><label>Course<select name="course"><option value="final">CA Final</option><option value="intermediate">CA Intermediate</option><option value="foundation">CA Foundation</option></select></label><label>Attempt<select name="attempt"><option value="">No indexed attempts</option></select></label><details><summary>More options</summary><label>Group<select name="group"><option value="both">Both groups</option><option value="1">Group I</option><option value="2">Group II</option></select></label><label>Language<select name="language"><option value="">All indexed languages</option><option value="en">English</option><option value="hi">Hindi</option></select></label><label><input type="checkbox" name="more"> More Resources</label></details></form><p role="status" data-resource-status></p><div data-resource-grid></div><details class="cc-official-directories"><summary>Official course directories and existing references</summary><div data-resource-directories></div></details><p data-resource-disclaimer class="cc-resource-disclaimer"></p></section>';}
    public static function admin_editor(){
        if(!CAFCC_Repository::admin_allowed())return;
        wp_enqueue_script('cafcc-resource-admin-v8',plugins_url('assets/resource-admin-v8.js',CAFCC_FILE),array(),CAFCC_VERSION,true);wp_localize_script('cafcc-resource-admin-v8','CAFCCResourceAdmin',array('url'=>rest_url('cafcc/v10/admin/resource-index'),'nonce'=>wp_create_nonce('wp_rest'),'courses'=>CAFCC_Courses::all()));
        echo '<section data-resource-index-admin><h2>Course / attempt PDF matrix</h2><p>Exact verified ICAI PDF links and existing exact-hash public Drive copies only. Known source-register copies appear automatically. The mislabelled examination upload is not treated as a question-only paper.</p><p role="status"></p><button type="button" class="button" data-resource-new>New resource</button><form><input type="hidden" name="id" value="0"><input type="hidden" name="expected_revision" value="0">';
        $selects=array('course'=>array('final'=>'CA Final','intermediate'=>'CA Intermediate','foundation'=>'CA Foundation'),'subject_key'=>array(),'resource_type'=>array('rtp'=>'RTP','mtp'=>'MTP','exam'=>'Examination Question Paper','suggested_answers'=>'Suggested Answers','study_material'=>'Study Material','supplementary'=>'Supplementary Material','notification'=>'Official Notification'),'series'=>array(''=>'No series','I'=>'Series I','II'=>'Series II'),'language'=>array('en'=>'English','hi'=>'Hindi'),'availability'=>array('available'=>'Verified available PDF','not_released'=>'Not yet released — verified official notice'));
        foreach($selects as $key=>$choices){echo '<p><label>'.esc_html(str_replace('_',' ',ucfirst($key))).' <select name="'.esc_attr($key).'">';foreach($choices as $value=>$label)echo '<option value="'.esc_attr($value).'">'.esc_html($label).'</option>';echo '</select></label></p>';}
        foreach(array('title'=>'Source title','url'=>'Exact PDF / availability notice HTTPS URL','source_hash'=>'Source SHA-256 (required for Drive copies)','attempt_month'=>'Attempt month (1–12)','attempt_year'=>'Attempt year') as $key=>$label)echo '<p><label>'.esc_html($label).'<br><input style="width:min(700px,95%)" type="'.(in_array($key,array('attempt_month','attempt_year'),true)?'number':($key==='url'?'url':'text')).'" name="'.esc_attr($key).'"'.($key==='source_hash'?'':' required').'></label></p>';
        echo '<label><input type="checkbox" name="publish_confirmed"> I verified this exact source, course, attempt, role and student accessibility; publish this metadata revision.</label><p><button type="submit" class="button button-primary">Save indexed resource</button></p></form><div data-resource-index-list></div></section>';
    }
    public static function init(){add_action('rest_api_init',function(){register_rest_route('cafcc/v10','/resources',array('methods'=>'GET','permission_callback'=>'__return_true','callback'=>array(__CLASS__,'matrix')));register_rest_route('cafcc/v10','/admin/resource-index',array(array('methods'=>'GET','permission_callback'=>function($r){return CAFCC_REST::permission($r,true);},'callback'=>function(){global $wpdb;return $wpdb->get_results('SELECT * FROM '.self::table().' ORDER BY id DESC LIMIT 200',ARRAY_A);}),array('methods'=>'POST','permission_callback'=>function($r){return CAFCC_REST::permission($r,true);},'callback'=>function($r){$d=CAFCC_Studio::body($r,10000);return is_wp_error($d)?$d:self::save($d);})));
    });}
